<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="alternate icon" type="image/x-icon" href="/favicon.ico"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><meta name="theme-color" content="#173f3b"><meta name="description" content="Concierge de voz bilingüe para el hotel ficticio Mirador Azul. Proyecto de demostración con datos de prueba."><meta property="og:type" content="website"><meta property="og:title" content="Mirador Azul | Voice Concierge"><meta property="og:image" content="<?= esc(base_url('social-preview.jpg')) ?>"><title>Mirador Azul · Admin</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/admin-lte@4.0.0/dist/css/adminlte.min.css"><style>body{background:#f1f5f2}.app-header{background:#173f3d;color:white}.brand{font-weight:700;letter-spacing:.08em}.content{max-width:1250px;margin:auto;padding:32px}.card{margin-bottom:24px}.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.faq-grid label{font-size:12px;font-weight:700}.faq-grid input,.faq-grid textarea{width:100%;display:block;padding:9px;border:1px solid #c9d9d2;border-radius:5px}.badge-demo{background:#d9ebdd;color:#24513f;padding:5px 9px;border-radius:20px;font-size:11px}@media(max-width:700px){.faq-grid{grid-template-columns:1fr}.content{padding:16px}}</style><link rel="stylesheet" href="/assets/brand.css"></head><body><nav class="app-header navbar navbar-expand"><div class="container-fluid"><span class="brand"><span class="brand-emblem" aria-hidden="true">M</span><span>MIRADOR AZUL<small>VOICE OPERATIONS</small></span></span><div class="ms-auto"><a class="text-white me-4" href="/">Simulador</a><a class="text-white" href="/logout">Salir</a></div></div></nav><main class="content"><div class="admin-cover"><span>HOTEL MIRADOR AZUL <b>·</b> CONCIERGE OPERATIONS</span></div><div class="d-flex justify-content-between align-items-center mb-4"><div><h1>Voice Concierge</h1><p>Hotel y registros de demostración</p></div><span class="badge-demo">SHIELD · ADMINLTE</span></div><?php if(session('message')): ?><div class="alert alert-success"><?= esc(session('message')) ?></div><?php endif ?><?php if(session('error')): ?><div class="alert alert-danger"><?= esc(session('error')) ?></div><?php endif ?><div class="row mb-4"><div class="col-md-4"><div class="card card-body"><small>LLAMADAS</small><h2><?= count($calls) ?></h2></div></div><div class="col-md-4"><div class="card card-body"><small>SOLICITUDES</small><h2><?= count($requests) ?></h2></div></div><div class="col-md-4"><div class="card card-body"><small>RESPUESTAS</small><h2><?= count($faqs) ?></h2></div></div></div><div class="card"><div class="card-header"><h3 class="card-title">Solicitudes ficticias</h3></div><div class="card-body table-responsive"><table class="table"><thead><tr><th>Nombre</th><th>Fecha solicitada</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($requests as $request): ?><tr><td><?= esc($request['guest_name']) ?></td><td><?= esc($request['requested_date']) ?></td><td><?= esc($request['status']) ?></td><td><?php if($request['status']==='new'): ?><form action="/admin/request/<?= (int)$request['id'] ?>" method="post"><?= csrf_field() ?><button class="btn btn-sm btn-outline-success">Marcar revisada</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div><div class="card"><div class="card-header"><h3 class="card-title">Llamadas recientes</h3></div><div class="card-body table-responsive"><table class="table"><thead><tr><th>ID</th><th>Idioma</th><th>Estado</th><th>Preguntas</th></tr></thead><tbody><?php foreach($calls as $call): ?><tr><td><?= esc(substr($call['call_sid'],0,12)) ?>…</td><td><?= esc($call['locale']) ?></td><td><?= esc($call['state']) ?></td><td><?= (int)$call['question_count'] ?></td></tr><?php endforeach ?></tbody></table></div></div><h2 class="mt-5 mb-3">Base de respuestas</h2><?php foreach($faqs as $faq): ?><div class="card card-body"><form action="/admin/faq/<?= (int)$faq['id'] ?>" method="post"><?= csrf_field() ?><div class="faq-grid"><?php foreach(['question_es'=>'Pregunta ES','answer_es'=>'Respuesta ES','question_en'=>'Question EN','answer_en'=>'Answer EN'] as $key=>$label): ?><label><?= $label ?><textarea name="<?= $key ?>" rows="2" required maxlength="500"><?= esc($faq[$key]) ?></textarea></label><?php endforeach ?></div><button class="btn btn-success mt-3">Guardar respuesta</button></form></div><?php endforeach ?></main></body></html>

